('ben-bradford','Ben Bradford — public writing','https://politicalquarterly.org.uk/authors/ben-bradford/','politicalquarterly.org.uk','Ben Bradford — public writing','Public commentary by a policing researcher on trust, legitimacy and the pressures facing policing, collected on the Political Quarterly author page. Commentary should be read alongside the original studies it discusses.',null,'GB',array['GB']::text[],array['Researcher','Blog']::text[],array['Commentary']::text[],array[]::text[],array['Neighbourhood policing','Leadership']::text[],array['en']::text[],'mixed','2026-10-14T00:00:00Z'::timestamptz,'editor_added','published',now()),
('uchile-cesc','University of Chile — Centre for Citizen Security Studies','https://cesc.uchile.cl/publicaciones/','cesc.uchile.cl','Centro de Estudios en Seguridad Ciudadana, Universidad de Chile','University publications on citizen security, policing, violence prevention and programme evaluation in Latin America. The collection includes work on public perceptions of police and evaluated practice examples.',null,'CL',array['CL','region:South America']::text[],array['University','Academic','Research collection']::text[],array['Original research','Practice examples','Implementation guides']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing','Violence prevention']::text[],array['es']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('usp-nev','University of São Paulo — Violence Research Centre','https://nev.prp.usp.br/publicacao/','nev.prp.usp.br','Núcleo de Estudos da Violência da Universidade de São Paulo','University research collection on violence, police legitimacy, rights and criminal justice in Brazil. Portuguese publication summaries sit alongside some English-language article information and links to published research.',null,'BR',array['BR']::text[],array['University','Academic','Research collection']::text[],array['Original research']::text[],array[]::text[],array['Violence prevention','Neighbourhood policing','Safeguarding']::text[],array['pt','en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('cleen-foundation','CLEEN Foundation — research publications','https://cleen.org/books/','cleen.org','CLEEN Foundation','Nigerian civil-society research and practical publications on police reform, accountability, public safety and justice. Its books collection includes surveys, reform audits and training resources, alongside organisational reports.',null,'NG',array['NG']::text[],array['Charity','Independent','Research collection']::text[],array['Original research','Implementation guides','Learning resources']::text[],array[]::text[],array['Neighbourhood policing','Safeguarding','Leadership']::text[],array['en']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('korea-police-science','Korean National Police University — Police Science Institute reports','https://psi.police.ac.kr/police/board/list.do?bbsId=BBSMSTR_000000000153&menuNo=115003000000','psi.police.ac.kr','경찰대학 치안정책연구소','Police university research reports on procedural justice, police legitimacy, organisational characteristics, crime and technology. The Korean-language catalogue provides report records and attachments; it is distinct from the Korean Institute of Criminology and Justice.',null,'KR',array['KR']::text[],array['University','Academic','Official','Research collection']::text[],array['Original research']::text[],array[]::text[],array['Neighbourhood policing','Leadership','Technology','Violence prevention']::text[],array['ko']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('taiwan-cpu-publications','Central Police University — publications and police knowledge repository','https://www.cpu.edu.tw/p/412-1000-45.php','cpu.edu.tw','中央警察大學','University publication gateway linking police studies periodicals, a police knowledge repository, theses and forensic science journals. It distinguishes publication searches from an electronic-resource service restricted to university staff and students.',null,'TW',array['TW']::text[],array['University','Academic','Official','Research collection']::text[],array['Original research']::text[],array[]::text[],array['Crime prevention','Investigations','Technology']::text[],array['zh']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('laspad-hira','Gaston Berger University — HIRA safeguarding research','https://laspad.org/programme/?prog=hira','laspad.org','LASPAD, Université Gaston Berger de Saint-Louis','University research on support for girls and women affected by sexual and gender-based violence in Senegal. Public resources include a service model, accommodation mapping and a directory of support centres.',null,'SN',array['SN']::text[],array['University','Academic','Research collection']::text[],array['Original research','Implementation guides']::text[],array[]::text[],array['Safeguarding','Violence prevention']::text[],array['fr']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('inacipe-journal','INACIPE — Mexican Journal of Criminal Sciences','https://revistacienciasinacipe.fgr.org.mx/index.php/02','revistacienciasinacipe.fgr.org.mx','Instituto Nacional de Ciencias Penales','Criminal sciences journal from Mexico’s National Institute of Criminal Sciences. It publishes research and analysis on crime, victimology, criminal policy, forensic sciences and justice; legal discussions concern their stated jurisdictions.',null,'MX',array['MX']::text[],array['Academic','Official','Research collection']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Crime prevention','Investigations','Safeguarding','Technology']::text[],array['es']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('flacso-urvio','FLACSO Ecuador — URVIO security studies journal','https://revistas.flacsoandes.edu.ec/urvio','revistas.flacsoandes.edu.ec','FLACSO Ecuador','FLACSO Ecuador journal covering citizen security, policing, violence and crime in Latin America. Its archive includes research articles and discussions of prevention and security policy, rather than only evaluated interventions.',null,'EC',array['EC','region:South America']::text[],array['University','Academic','Research collection']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Crime prevention','Neighbourhood policing','Violence prevention']::text[],array['es']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('delito-sociedad','Delito y Sociedad — university criminology journal','https://bibliotecavirtual.unl.edu.ar/publicaciones/index.php/DelitoySociedad','bibliotecavirtual.unl.edu.ar','Universidad Nacional del Litoral and Universidad de Buenos Aires','Argentine university journal on crime, policing, criminal justice and social control. Public university notices and institutional article records link research on community policing, police organisations and criminal justice practices.',null,'AR',array['AR']::text[],array['University','Academic','Research collection']::text[],array['Original research','Commentary']::text[],array[]::text[],array['Neighbourhood policing','Crime prevention','Leadership']::text[],array['es']::text[],'free','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('met-research','Metropolitan Police — research and analysis','https://www.met.police.uk/police-forces/metropolitan-police/areas/about-us/about-the-met/research/research-analysis-met/','met.police.uk','Metropolitan Police Service','Published evaluations from the Met’s Strategic Insight Unit, including supervisor reviews of body-worn video and procedural justice training. The collection explains methods, findings and limitations, with links to the underlying reports.',null,'GB',array['GB']::text[],array['Official','Research collection']::text[],array['Original research','Research summaries']::text[],array['Randomised controlled trials','Mixed methods']::text[],array['Neighbourhood policing','Leadership','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('hampshire-vrp-evaluations','Hampshire and Isle of Wight — violence reduction evaluations','https://www.hampshire-pcc.gov.uk/vru-home/evidence-based-practice','hampshire-pcc.gov.uk','Office of the Police and Crime Commissioner for Hampshire and the Isle of Wight','Local evaluations commissioned through the violence reduction partnership, covering trauma-informed policing, custody and hospital navigators, focused deterrence and support for young people. Reports concern different programmes and should be assessed separately.',null,'GB',array['GB']::text[],array['Official','Research collection']::text[],array['Original research','Practice examples']::text[],array[]::text[],array['Violence prevention','Safeguarding','Police wellbeing']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('kent-medway-vru','Kent and Medway Violence Reduction Unit — reports','https://kentandmedwayvru.co.uk/about-us/vru-reports/','kentandmedwayvru.co.uk','Kent and Medway Violence Reduction Unit','A local collection of violence reduction reports, strategic needs assessments and an external evaluation by Cordis Bright. It provides evidence about local needs and delivery alongside annual activity reports; these are different forms of evidence.',null,'GB',array['GB']::text[],array['Official','Research collection']::text[],array['Original research','Datasets','Practice examples']::text[],array[]::text[],array['Violence prevention','Safeguarding']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('n8-policing','N8 Policing Research Partnership — research and public writing','https://www.n8prp.org.uk/home/research/small-grants/','n8prp.org.uk','N8 Policing Research Partnership','Police–university collaboration publishing research reports, Agile Evidence Reviews and accessible writing by researchers and practitioners. Topics include vulnerability, custody, police culture, domestic abuse and changing demand. Reviews and individual studies retain their own scope and limitations.',null,'GB',array['GB']::text[],array['University','Academic','Research collection','Blog']::text[],array['Original research','Evidence reviews','Research summaries','Commentary']::text[],array['Systematic reviews']::text[],array['Investigations','Safeguarding','Police wellbeing','Leadership','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('icpr-policing','Birkbeck ICPR — policing and the policed','https://icpr.org.uk/theme/policing-and-policed','icpr.org.uk','Institute for Crime & Justice Policy Research, Birkbeck, University of London','University research and publications on policing organisations, effectiveness and relationships with the public. Projects cover procedural justice, police complaints, fraud, professionalisation and the use of evidence, with links to papers and working reports.',null,'GB',array['GB']::text[],array['University','Academic','Research collection']::text[],array['Original research','Research summaries']::text[],array[]::text[],array['Investigations','Neighbourhood policing','Leadership','Safeguarding']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('bsc-policing-blog','British Society of Criminology Policing Network — blog','https://bscpolicingnetwork.wordpress.com/pn-blog/','bscpolicingnetwork.wordpress.com','British Society of Criminology Policing Network','Accessible contributions by policing researchers, including doctoral researchers, explaining their studies and debating practice. Posts link to research on police culture, wellbeing, decision-making, violence prevention and reform. Some contributions report preliminary findings or personal interpretation.',null,'GB',array['GB']::text[],array['Professional society','Academic','Blog']::text[],array['Research summaries','Commentary']::text[],array[]::text[],array['Neighbourhood policing','Leadership','Police wellbeing','Technology','Violence prevention']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('politieacademie-research','Netherlands Police Academy — knowledge and research','https://www.politieacademie.nl/kennis-en-onderzoek','politieacademie.nl','Politieacademie','Dutch-language police research, publication links, podcasts and practical knowledge from the Police Academy. Its centres cover local policing, investigation, digital technology and police organisations. The public research pages link to the police library; access to individual services varies.',null,'NL',array['NL']::text[],array['Official','Academic','Learning provider']::text[],array['Original research','Research summaries','Learning resources']::text[],array[]::text[],array['Neighbourhood policing','Investigations','Leadership','Technology','Police wellbeing']::text[],array['nl']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('gruene-liste-praevention','Grüne Liste Prävention — prevention evidence register','https://www.gruene-liste-praevention.de/nano.cms/datenbank/information','gruene-liste-praevention.de','Lower Saxony Crime Prevention Council, in cooperation with Hannover Medical School','German-language evidence register of prevention programmes for children, young people, families and communities. Entries distinguish levels of evaluation evidence and implementation quality. It covers wider prevention and health promotion as well as violence, rather than police interventions alone.',null,'DE',array['DE']::text[],array['Official','Academic','Research collection']::text[],array['Evidence reviews','Research summaries','Implementation guides']::text[],array[]::text[],array['Crime prevention','Violence prevention','Safeguarding']::text[],array['de']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('jeff-asher','Jeff-alytics — Jeff Asher','https://jasher.substack.com/','jasher.substack.com','Jeff Asher','A named Substack newsletter and podcast analysing crime data and how crime trends are measured, with interviews with criminologists and policing researchers. Its focus is mainly American; data commentary and interviews should be distinguished from evaluated policing interventions.',null,'US',array['US']::text[],array['Researcher','Independent','Blog']::text[],array['Original research','Commentary','Research summaries']::text[],array[]::text[],array['Crime prevention','Violence prevention','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('john-shjarback','Shjarstack — John Shjarback','https://johnshjarback.substack.com/','johnshjarback.substack.com','John Shjarback','Public writing by a policing researcher, connecting studies with debates about police practice, community policing and mental health responses. Named posts discuss evidence and link to research; the author’s main website also provides reports, evaluations and replication materials.',null,'US',array['US']::text[],array['Researcher','Academic','Blog']::text[],array['Original research','Research summaries','Commentary']::text[],array[]::text[],array['Neighbourhood policing','Leadership','Police wellbeing','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('matt-ashby','Matt Ashby — crime research and public writing','https://lesscrime.info/post/','lesscrime.info','Matt Ashby','Public data analysis, charts and explanations by a crime science researcher, with a linked publication collection and free-to-read versions where available. Topics include homicide, crime concentration, police demand and interpreting trends, alongside practical research and data tutorials.',null,'GB',array['GB']::text[],array['Researcher','Academic','Blog']::text[],array['Original research','Research summaries','Commentary','Learning resources']::text[],array[]::text[],array['Crime prevention','Violence prevention','Technology','Leadership']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now()),
('bit-crime-justice','Behavioural Insights Team — crime, justice and security','https://www.bi.team/focus-areas/government-society/crime-justice-security/','bi.team','Behavioural Insights Team','Research reports and public writing applying behavioural science to crime, justice and policing, including violence reduction, victim participation and work with police analytical teams. The named Behavioural Insights Medium archive provides further writing; reports and commentary require separate appraisal.',null,'GB',array['GB']::text[],array['Company','Research collection','Blog']::text[],array['Original research','Research summaries','Practice examples','Commentary']::text[],array[]::text[],array['Crime prevention','Violence prevention','Safeguarding','Technology']::text[],array['en']::text[],'mixed','2026-10-15T00:00:00Z'::timestamptz,'editor_added','published',now())
on conflict (slug) do nothing;

