-- Accepted editorial AI-assisted descriptions only; do not translate papers or
-- relabel them human translations. Preserve live edits and invalidated versions.
insert into public.source_ai_translations(source_id,locale,about,original_about,accepted_at)
select s.id,t.locale,t.about,t.original_about,now() from (values
('college-toolkit','fr','Des synthèses d’interventions de réduction de la criminalité, avec des liens vers des revues systématiques et des informations sur la mise en œuvre, les coûts et les contextes étudiés.','Summaries of crime reduction interventions, with links to systematic reviews and information about implementation, costs and settings where interventions were studied.'),
('college-toolkit','es','Resúmenes de intervenciones para reducir la delincuencia, con enlaces a revisiones sistemáticas e información sobre aplicación, costes y contextos estudiados.','Summaries of crime reduction interventions, with links to systematic reviews and information about implementation, costs and settings where interventions were studied.'),
('global-policing-database','fr','Une base de données sur abonnement recensant des évaluations internationales d’interventions policières, avec des informations consultables sur les études et des liens vers des articles, rapports et thèses.','A subscription database of international evaluations of policing interventions, with searchable study details and links to published papers, reports and theses.'),
